contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount, address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount >= 100);
        require(address(this).balance >= amount);

        uint256 cBalanceBefore = address(c).balance;

        bool firstSucceeded;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstSucceeded = false;
        } else {
            firstSucceeded = true;
        }

        assert(!firstSucceeded || address(c).balance == cBalanceBefore - 100);
    }
}

